"""Objects injected into the routes by FastAPI.

The routes never build services themselves: they receive them here.
This makes it easy to swap the real model for a fake one in tests.
"""

import re

from fastapi import Header, HTTPException, Request, status

from chat.service import ChatService
from config.settings import Settings
from inference.service import InferenceService

# A device id is generated by the browser (UUID). Kept strict to avoid abuse.
DEVICE_ID_PATTERN = re.compile(r"^[A-Za-z0-9_-]{8,64}$")


def get_inference_service(request: Request) -> InferenceService:
    """The service created at startup by backend/main.py."""
    return request.app.state.inference_service


def get_chat_service(request: Request) -> ChatService:
    return request.app.state.chat_service


def get_app_settings(request: Request) -> Settings:
    return request.app.state.settings


def get_device_id(x_device_id: str = Header(..., description="Identifiant de l'appareil (UUID)")) -> str:
    """No login: conversations belong to the device id sent in the X-Device-Id header."""
    if not DEVICE_ID_PATTERN.match(x_device_id):
        raise HTTPException(status.HTTP_400_BAD_REQUEST, "Invalid X-Device-Id header.")
    return x_device_id
